const BASE = "https://spark-47d8.tail333a1d.ts.net/agentmem/v1";
// Prototype: paste the test token. Production: return the Supabase access token.
const getToken = () => "<PASTE_TEST_TOKEN>";

type Tier = "fast" | "balanced" | "local" | "auto" | "max" | "openrouter";
// Per-task tool scope: a named profile or an explicit allowlist.
type ToolScope = { profile?: string; tools?: string[] };
// Token usage returned on chat/act/fanout responses (act/fanout sum across the loop).
type Usage = { input: number; output: number; total: number };
// Quality/speed: pass `tier`, OR an explicit `model` (a bare id -> local Ollama pool,
// a "vendor/model" slug -> a configured OpenAI-compatible backend). `model` wins routing.
type ModelOpt = { tier?: Tier; model?: string };

async function api(path: string, init: RequestInit = {}) {
  const res = await fetch(BASE + path, {
    ...init,
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${getToken()}`,
      ...(init.headers || {}),
    },
  });
  if (res.status === 429) {
    const retry = res.headers.get("retry-after");
    throw new Error(`rate limited; retry after ${retry ?? "?"}s`);
  }
  if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
  return res.status === 204 ? null : res.json();
}

export const AgentMemory = {
  listAgents: () => api("/agents"),
  spawn: (agentType: string, label?: string) =>
    api("/agents", { method: "POST", body: JSON.stringify({ agentType, label }) }),
  remember: (id: string, text: string | string[]) =>
    api(`/agents/${id}/memories`, { method: "POST", body: JSON.stringify({ text }) }),
  recall: (id: string, query: string, k = 5) =>
    api(`/agents/${id}/recall`, { method: "POST", body: JSON.stringify({ query, k }) }),
  searchBase: (query: string, k = 5) =>
    api("/memory/search", { method: "POST", body: JSON.stringify({ query, k }) }),
  terminate: (id: string) => api(`/agents/${id}`, { method: "DELETE" }),

  // tier/model = quality/speed knob; usually you never name a model.
  // Returns { text, provider, model, usedMemories, usage } (usage: Usage).
  chat: (id: string, prompt: string, opts: { recallK?: number } & ModelOpt = {}) =>
    api(`/agents/${id}/chat`, { method: "POST", body: JSON.stringify({ prompt, ...opts }) }),

  // Agentic loop: the model uses tools (run_code in the sandbox, recall, remember, and any
  // permitted external tools) to do work. Scope tools with `profile` or `tools`.
  // Returns { text, steps: [{tool, args, result}], usedMemories, provider, model, usage }
  // where `usage` is summed across every model call in the loop.
  act: (
    id: string,
    prompt: string,
    opts: { maxSteps?: number; recallK?: number } & ModelOpt & ToolScope = {},
  ) => api(`/agents/${id}/act`, { method: "POST", body: JSON.stringify({ prompt, ...opts }) }),

  // Fan-out: up to 8 ephemeral workers run tasks in parallel, then are dismissed.
  // tasks: string[] OR { prompt, tools?, profile? }[] for per-task tool scoping.
  // Aggregated result includes `usage` summed across all sub-agents.
  fanout: (
    id: string,
    tasks: (string | { prompt: string; tools?: string[]; profile?: string })[],
    opts: { agentType?: string; maxStepsPer?: number } & ModelOpt & ToolScope = {},
  ) => api(`/agents/${id}/fanout`, { method: "POST", body: JSON.stringify({ tasks, ...opts }) }),

  // Direct sandboxed code execution (python | node | bash; no network).
  runCode: (language: string, code: string, timeoutMs?: number) =>
    api("/sandbox/run", { method: "POST", body: JSON.stringify({ language, code, timeoutMs }) }),

  // Streaming chat — fetch + reader (NOT EventSource, which can't send auth headers).
  async chatStream(
    id: string,
    prompt: string,
    onDelta: (t: string) => void,
    opts: ModelOpt = {},
  ) {
    const res = await fetch(`${BASE}/agents/${id}/chat`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "text/event-stream",
        authorization: `Bearer ${getToken()}`,
      },
      body: JSON.stringify({ prompt, ...opts }),
    });
    if (res.status === 429) throw new Error(`rate limited; retry after ${res.headers.get("retry-after") ?? "?"}s`);
    const reader = res.body!.getReader();
    const dec = new TextDecoder();
    let buf = "";
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      const lines = buf.split("\n");
      buf = lines.pop()!;
      for (const ln of lines) {
        const t = ln.trim();
        if (!t.startsWith("data:")) continue;
        const p = t.slice(5).trim();
        if (p === "[DONE]") return;
        try { const { delta } = JSON.parse(p); if (delta) onDelta(delta); } catch {}
      }
    }
  },
};
