curl -s -H "$AUTH" -H "$CT" -d '{
  "language": "python",
  "code": "print(sum(range(100)))",
  "timeoutMs": 5000
}' $BASE/sandbox/run
# -> {stdout:"4950\n", stderr:"", exitCode:0, ...}
