// agent-memory.js — per-agent COW memory for ruflo-style multi-agent workflows.
//
// Model:
//   MemoryHub  = one shared, embedded base memory (common knowledge).
//   Agent      = a copy-on-write fork of the base (~162 B / ~7 ms regardless of
//                base size). Each agent reads base ∪ its own edits, child wins,
//                with private writes, tombstones, checkpoint/rollback, and the
//                ability to PROMOTE vetted learnings back into the shared base.
//
// Text is stored alongside each vector, so recall() returns the actual memory
// content plus which lineage node it came from ('base' vs the agent's branch).

import { open, AgenticMemory } from 'agenticow';
import { embed, embedBatch, DIM } from './embedder.js';

// Keep id spaces disjoint so base facts and per-agent private memories never
// collide by accident (a real collision would mean "agent overrides base fact").
const BASE_ID_BASE = 1;           // base knowledge: 1, 2, 3, ...
const AGENT_ID_BASE = 1_000_000_000; // agent N private: 1e9 + N*1e6 + seq

// Return a vector per entry: use the persisted one when present, embed only the
// rest — so a rehydrate from a vector-bearing durable log does ZERO embedding.
async function vectorsFor(entries) {
  const missing = [];
  for (let i = 0; i < entries.length; i++) if (!entries[i].vector) missing.push(i);
  const embedded = missing.length ? await embedBatch(missing.map((i) => entries[i].text)) : [];
  const out = new Array(entries.length);
  let m = 0;
  for (let i = 0; i < entries.length; i++) out[i] = entries[i].vector || embedded[m++];
  return out;
}

export class MemoryHub {
  /** @param {AgenticMemory} mem  @param {string} path  @param {import('./durable-store.js').DurableStore} [store] */
  constructor(mem, path, store = null) {
    this.mem = mem;
    this.path = path;
    this.store = store; // durable text log (source of truth across restarts)
    this._baseSeq = 0;
    this._agentCount = 0;
  }

  /** Create a fresh shared base memory at `path`. */
  static create(path, store = null) {
    const mem = open(path, { dimension: DIM, metric: 'cosine' });
    return new MemoryHub(mem, path, store);
  }

  /** Reopen a base saved earlier with hub.save(manifestPath). NOTE: agenticow
   * persists vectors but not text — prefer rebuilding from the DurableStore. */
  static load(manifestPath, store = null) {
    const mem = AgenticMemory.load(manifestPath);
    const hub = new MemoryHub(mem, manifestPath, store);
    hub._baseSeq = mem.status().totalVectors;
    return hub;
  }

  /** Re-ingest base records with explicit ids + text (rehydrate path). Uses each
   *  entry's persisted vector; only entries WITHOUT one are (re-)embedded. */
  async ingestRaw(entries) {
    if (!entries.length) return;
    const vecs = await vectorsFor(entries);
    this.mem.ingest(entries.map((e, i) => ({ id: e.id, vector: vecs[i], text: e.text })));
    for (const e of entries) // advance the base id counter past anything restored
      if (e.id >= BASE_ID_BASE && e.id < AGENT_ID_BASE)
        this._baseSeq = Math.max(this._baseSeq, e.id - BASE_ID_BASE + 1);
  }

  /**
   * Embed and ingest shared knowledge into the base.
   * @param {string[]} facts
   * @returns {Promise<number[]>} the ids assigned
   */
  async addKnowledge(facts) {
    const list = Array.isArray(facts) ? facts : [facts];
    const vecs = await embedBatch(list);
    const records = list.map((text, i) => ({
      id: BASE_ID_BASE + this._baseSeq + i,
      vector: vecs[i],
      text,
    }));
    this._baseSeq += list.length;
    this.mem.ingest(records);
    if (this.store) this.store.record('base', records);
    return records.map((r) => r.id);
  }

  /**
   * Spawn a per-agent COW branch off the shared base.
   * @param {string} name      branch label (use the ruflo agentId to bind them)
   * @param {number} [idx]     id-space slot; pass a stable value (e.g. derived
   *                           from the agentId) so private ids are reproducible.
   */
  spawn(name, idx = this._agentCount++) {
    const branch = this.mem.fork(name);
    return new Agent(branch, name, idx, this.store);
  }

  /** Top-k recall against the shared base only. */
  async recall(query, k = 5) {
    const v = await embed(query);
    return this.mem.query(v, k).map(hitToObj);
  }

  status() { return this.mem.status(); }
  save(manifestPath) { return this.mem.save(manifestPath); }
  close() { this.mem.close(); }
}

export class Agent {
  /** @param {AgenticMemory} branch @param {string} name @param {number} idx @param {import('./durable-store.js').DurableStore} [store] */
  constructor(branch, name, idx, store = null) {
    this.branch = branch;
    this.name = name;
    this.idx = idx;
    this.store = store;
    this._seq = 0;
  }

  _nextId() {
    return AGENT_ID_BASE + this.idx * 1_000_000 + this._seq++;
  }

  /** Re-ingest this branch's records with explicit ids + text (rehydrate path).
   *  Uses persisted vectors; only entries WITHOUT one are (re-)embedded. */
  async ingestRaw(entries) {
    if (!entries.length) return;
    const vecs = await vectorsFor(entries);
    this.branch.ingest(entries.map((e, i) => ({ id: e.id, vector: vecs[i], text: e.text })));
    const base = AGENT_ID_BASE + this.idx * 1_000_000;
    for (const e of entries) this._seq = Math.max(this._seq, e.id - base + 1);
  }

  /**
   * Store a private memory for this agent only.
   * @param {string|string[]} text
   * @returns {Promise<number[]>} ids written
   */
  async remember(text) {
    const list = Array.isArray(text) ? text : [text];
    const vecs = await embedBatch(list);
    const records = list.map((t, i) => ({ id: this._nextId(), vector: vecs[i], text: t }));
    this.branch.ingest(records);
    if (this.store) { this.store.record(this.name, records); await this.store.flushAsync(); } // durable before ack
    return records.map((r) => r.id);
  }

  /**
   * Inherit shared text into THIS branch with FRESH own-slot ids — used to replay
   * a tenant's graduated base (durable scope `tbase:<tenant>`) into every one of
   * that tenant's agent branches, so they see their tenant's vetted learnings
   * without those learnings touching the cross-tenant global base.
   *
   * Unlike ingestRaw (which preserves source ids — wrong for foreign ids, they'd
   * corrupt this branch's _seq), this assigns ids in this agent's own id-space via
   * _nextId, and does NOT record to the durable store (the entries already live in
   * the durable `tbase:<tenant>` scope; recording them under this agentId would
   * re-graduate them on the next DELETE and multiply them on every spawn).
   * @param {{id?:number,text:string,vector?:Float32Array}[]} entries
   * @returns {Promise<number>} count inherited
   */
  async inherit(entries) {
    if (!entries || !entries.length) return 0;
    const vecs = await vectorsFor(entries);
    const records = entries.map((e, i) => ({ id: this._nextId(), vector: vecs[i], text: e.text }));
    this.branch.ingest(records);
    return records.length;
  }

  /** Recall over base ∪ this agent's private memories (child wins, tombstones masked). */
  async recall(query, k = 5) {
    const v = await embed(query);
    return this.branch.query(v, k).map(hitToObj);
  }

  /** Hide specific ids from this agent's view (tombstone). Works on base or private ids. */
  forget(ids) {
    return this.branch.delete(Array.isArray(ids) ? ids : [ids]);
  }

  /** Freeze a restore point before a risky batch. */
  checkpoint(label) { return this.branch.checkpoint(label); }

  /** Discard everything since the given checkpoint (or the last one). */
  rollback(checkpointId) { return this.branch.rollback(checkpointId); }

  /** What this agent has changed vs its parent: { added, overridden, deleted }. */
  diff() { return this.branch.diff(); }

  /** The COW chain for this agent (base → checkpoints → working). */
  lineage() { return this.branch.lineage(); }

  /**
   * Merge this agent's vetted learnings INTO the shared base, so every future
   * agent inherits them. Defaults to promoting into the fork's parent (the hub).
   * @param {MemoryHub} [hub]
   */
  promoteTo(hub) {
    return this.branch.promote(hub ? hub.mem : undefined);
  }

  close() { this.branch.close(); }
}

function hitToObj(h) {
  return { id: h.id, text: h.text, distance: Number(h.distance.toFixed(4)), source: h.branch };
}

