// durable-store.js — the persistence the agenticow .rvf manifest doesn't give us.
//
// agenticow saves VECTORS but not text payloads, so a reload loses all content.
// This is a tiny append-only log of {id, text, scope} (scope = 'base' or an
// agentId) that IS the durable source of truth. On boot the service rebuilds the
// in-RAM agenticow index from this log by re-embedding the text (the embedder is
// local + deterministic), so memory survives restarts/reboots WITH its text.

import fs from 'node:fs';
import path from 'node:path';

// Persist the embedding vector alongside the text so a restart doesn't have to
// RE-EMBED the whole corpus (boot cost was O(N embeddings)). Stored compactly as
// base64 of the Float32Array bytes.
const encV = (vec) => (vec ? Buffer.from(Float32Array.from(vec).buffer).toString('base64') : undefined);
const decV = (b64) => {
  if (!b64) return undefined;
  const buf = Buffer.from(b64, 'base64');
  return new Float32Array(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
};

export class DurableStore {
  /** @param {string} filePath */
  constructor(filePath) {
    this.filePath = filePath;
    /** @type {{id:number, text:string, scope:string}[]} */
    this.entries = [];
    this._timer = null;
    if (fs.existsSync(filePath)) {
      const raw = fs.readFileSync(filePath, 'utf8');
      try {
        this.entries = JSON.parse(raw).entries || [];
      } catch {
        // NEVER silently blank a corrupt log — that's total memory loss. Preserve
        // it and refuse to start so an operator can inspect/restore.
        const bak = `${filePath}.corrupt.${Date.now()}`;
        try { fs.writeFileSync(bak, raw); } catch { /* best effort */ }
        throw new Error(`durable store ${filePath} is corrupt (backed up to ${bak}); refusing to start to avoid wiping memory.`);
      }
    }
  }

  /** Append memories. @param {string} scope @param {{id:number,text:string,vector?:Float32Array}[]} items */
  record(scope, items) {
    for (const r of (Array.isArray(items) ? items : [items])) {
      if (r && typeof r.id === 'number') {
        const e = { id: r.id, text: r.text, scope };
        const v = encV(r.vector);
        if (v) e.v = v; // persist embedding so rehydrate skips re-embedding
        this.entries.push(e);
      }
    }
    this._persist();
  }

  /**
   * Graduation: re-scope an agent's memories (ids unchanged). Targets the global
   * shared `base` by default (legacy), or a per-tenant base scope `tbase:<tenant>`
   * so a tenant's vetted learnings stay isolated to that tenant.
   * @param {string} scope     the agent scope to graduate
   * @param {string} [toScope] destination scope (default 'base')
   */
  graduate(scope, toScope = 'base') {
    let n = 0;
    for (const e of this.entries) if (e.scope === scope) { e.scope = toScope; n++; }
    if (n) this._persist();
    return n;
  }

  /** Drop a scope's memories entirely (e.g. a hard delete). */
  dropScope(scope) {
    const before = this.entries.length;
    this.entries = this.entries.filter((e) => e.scope !== scope);
    if (this.entries.length !== before) this._persist();
  }

  /** @returns {Map<string, {id:number,text:string,vector?:Float32Array}[]>} scope -> entries */
  byScope() {
    const m = new Map();
    for (const e of this.entries) {
      if (!m.has(e.scope)) m.set(e.scope, []);
      m.get(e.scope).push({ id: e.id, text: e.text, vector: decV(e.v) });
    }
    return m;
  }

  count() { return this.entries.length; }

  _persist() {
    clearTimeout(this._timer);
    this._timer = setTimeout(() => this.flush(), 200);
  }

  /** Synchronous atomic write — call on shutdown to guarantee the latest is on disk. */
  flush() {
    clearTimeout(this._timer);
    fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
    fs.writeFileSync(this.filePath + '.tmp', JSON.stringify({ entries: this.entries }));
    fs.renameSync(this.filePath + '.tmp', this.filePath);
  }

  /** Async atomic write — await before acknowledging a write so a 201 never lies
   *  about durability (cancels the pending debounce; no double-write). */
  async flushAsync() {
    clearTimeout(this._timer);
    await fs.promises.mkdir(path.dirname(this.filePath), { recursive: true });
    await fs.promises.writeFile(this.filePath + '.tmp', JSON.stringify({ entries: this.entries }));
    await fs.promises.rename(this.filePath + '.tmp', this.filePath);
  }
}

