// embed-worker.js — runs the MiniLM ONNX embedder in a worker_thread so the model
// forward pass (CPU-bound) doesn't block the main event loop that serves all HTTP.
// Receives { id, texts }, replies { id, ok, buffer } where buffer is a transferable
// Float32Array of length texts.length*DIM (sliced back into per-text vectors).

import { parentPort } from 'node:worker_threads';
import { pipeline } from '@huggingface/transformers';

const MODEL_ID = 'Xenova/all-MiniLM-L6-v2';
const DIM = 384;

let extractorP = null;
const getExtractor = () => (extractorP ||= pipeline('feature-extraction', MODEL_ID));

parentPort.on('message', async ({ id, texts }) => {
  try {
    const ex = await getExtractor();
    const out = await ex(texts, { pooling: 'mean', normalize: true });
    const data = Float32Array.from(out.data); // length = texts.length * DIM
    parentPort.postMessage({ id, ok: true, count: texts.length, buffer: data.buffer }, [data.buffer]);
  } catch (e) {
    parentPort.postMessage({ id, ok: false, error: String((e && e.message) || e) });
  }
});

