// embedder.js — real text→vector embeddings, fully local.
//
// Uses Xenova/all-MiniLM-L6-v2 (384-dim, L2-normalized) via Transformers.js. The
// forward pass is CPU-bound and would block the single Node event loop that serves
// every HTTP request (recall embeds the query on EVERY call), so by default it runs
// in a worker_thread (./embed-worker.js). If the worker can't start, we transparently
// fall back to in-process embedding — same result, just on the main thread.
//
// Set EMBED_IN_PROCESS=1 to force the in-process path (e.g. for debugging).

import { Worker } from 'node:worker_threads';

export const MODEL_ID = 'Xenova/all-MiniLM-L6-v2';
export const DIM = 384;

const FORCE_IN_PROCESS = process.env.EMBED_IN_PROCESS === '1';

// ── worker path ────────────────────────────────────────────────────────────────
let worker = null;
let workerBroken = FORCE_IN_PROCESS;
let nextId = 1;
const pending = new Map();

function failWorker(err) {
  workerBroken = true;
  for (const p of pending.values()) p.reject(err);
  pending.clear();
