    const promoted = await this.graduate(agentId);
    const info = { agentId, agentType, promoted, reason: 'explicit' };
    if (this.onGraduate) this.onGraduate(info);
    return info;
  }

  /**
   * Release an ephemeral agent WITHOUT graduating its learnings: close its
   * branch, drop it from the bridge, mark it terminated in ruflo's store + swarm,
   * and purge its durable memories. Used for short-lived fan-out workers.
   */
  dismiss(agentId) {
    const a = this.agents.get(agentId);
    if (a) { try { a.close(); } catch {} this.agents.delete(agentId); }
    this.swarmOf.delete(agentId);
    this.typeOf.delete(agentId);
    this.tenantOfId.delete(agentId);
    const store = this._readAgentStore();
    const rec = (store.agents || {})[agentId];
    if (rec) { rec.status = 'terminated'; rec.terminatedAt = new Date().toISOString(); this._writeAgentStore(store); }
    const raw = this._readRaw();
    for (const sw of Object.values(raw.swarms || {})) if (sw.agents) sw.agents = sw.agents.filter((id) => id !== agentId);
    this._writeRaw(raw);
    if (this.hub.store) this.hub.store.dropScope(agentId);
  }

  /** Release all branches (does not touch the shared base). */
  close() {
    this.unwatch();
    for (const a of this.agents.values()) a.close();
    for (const a of this.tenantBases.values()) { try { a.close(); } catch { /* ignore */ } }
    this.agents.clear();
    this.tenantBases.clear();
  }
}
